UPDATE `matcheasy_new`.`c_job` SET `job_id`=1296, `company_id`=8038732, `project_id`=NULL, `job_name`='产业发展（招商）经理', `departments`=NULL, `citys`='广州', `job_duty`='职位要求：\n1、协助前期投拓工作；\n2、编制招商方案和预算费用，采取有效策略加快招商进度；\n3、解决招商中的问题，监督考核招商计划的执行情况；\n4、拟定招商政策、合同及相关文件，制作招商阶段性工作报告；\n5、参与部分策划工作，结合招商情况提出合理化建议；\n6、定期组织市场调研，熟悉市场动态，整理市场调研报告；\n7、建立招商企业服务体系，促进落地企业发展，提升公司品牌形象。\n任职要求：\n1、市场营销、企业管理、金融或房地产相关专业，本科及以上学历；\n2、3 年以上产业地产招商经理岗位任职经验，熟悉产业地产类项目的招商及落地发展的整\n体运作；\n3、具备产业地产项目前期取地、投拓协助、预招商等经验的优先考虑；\n4、负责定位及后期营销策划及执行能力，有若干项目实际操盘经验；\n5、具备敏锐的商业触觉，快速的市场反应及分析能力，能够随时了解并掌握新的产业地产\n动态及市场变化；\n6、具备良好的市场开拓能力及渠道资源；\n7、具备良好的沟通能力（具备熟练的英语沟通能力优先考虑）、管理能力和项目提案能力，\n具有团队作战精神及良好的人际关系。', `experi_qlft`=NULL, `proc_id`=NULL, `min_salary`=15.00, `max_salary`=25.00, `salary`='15k-25k', `emp_cnt`='', `click_cnt`=NULL, `degree_cond`='13', `school_cond`=NULL, `exp_cond`='5-10年', `start_date`=NULL, `end_date`=NULL, `recruit_type`=3, `special_cond`='10007,10008,10045,10046', `sys_recommend`=NULL, `child_job_flag`=1, `STATUS`=2, `create_id`=15790741, `create_time`='2022-05-17 02:11:05', `update_id`=NULL, `update_time`='2025-06-26 14:51:30', `district`=NULL, `trade_circle`=NULL, `subway_station`=NULL, `job_kind_id`='13,1322', `is_above`=2, `is_comp_addr`=NULL, `departments_name`='', `post_opt_com_1`=NULL, `post_opt_com_2`=NULL, `post_opt_com_3`=NULL, `audit_flag`=NULL, `pub_range`='0000000000', `introversion_status`=NULL, `bonus_status`=NULL, `min_exp`=5, `max_exp`=10, `old_job_id`=NULL, `keywords`='', `zbw_status`=NULL, `offer_resume_cnt`=0, `job51_channel_resume_cnt`=0, `zhilian_channel_resume_cnt`=0, `liepin_channel_resume_cnt`=0, `channel_resume_cnt`=0, `bonus_resume_cnt`=0, `introversion_resume_cnt`=0, `deliver_resume_cnt`=0, `resume_cnt`=NULL, `module`=13, `hunter_comp_type`=1, `hh_job_comp_id`=896932, `hh_job_comp_name`='五矿建设投资管理（北京）有限公司', `channel_comp_field`='', `channel_comp_field_id`='', `channel_comp_type`=NULL, `channel_comp_size`=NULL, `is_channel_job`=NULL, `inside_audits`=0, `is_anonymity`=0, `anonymity_inf