UPDATE `matcheasy_new`.`c_job` SET `job_id`=1389, `company_id`=8038732, `project_id`=NULL, `job_name`='投资并购经理', `departments`=NULL, `citys`='北京', `job_duty`='岗位职责：\n1.负责物业管理企业收并购业务（合资公司合作、股权并购等模式）落地；\n2.分析研究行业动态、收集市场信息；\n3.积极寻找可行物业收并购标的，开展物业公司拓展业务，提升企业整体业绩；\n4.配合上级完成对标的企业前期商务洽谈、可研立项、业务踏勘、尽调、合同签订、投后复盘等工作；\n5.负责项目风险监控、业务开展中的风险预知、风险规避、风险上报及总结。\n6.具有投资并购相关分析、投资、财务、法律等相关知识，有物业投资并购成功案例者优先。\n任职要求：\n1.营销、金融、财务、投资、法律等相关专业，统招本科及以上学历；\n2.5年以上工作经验，熟悉物业行业，3年以上地产或物业行业投资工作经验；\n3.具备投资并购相关分析、投资、财务、法律等相关知识，成功完成1-2个物业公司（项目）收并购项目。财务专业拥有CPA证书优先；\n4.具有较强的沟通、严谨的分析判断能力、出色的人际交往和公关能力；\n5.年龄45岁以下，能适应经常性出差工作。', `experi_qlft`=NULL, `proc_id`=NULL, `min_salary`=25.00, `max_salary`=30.00, `salary`='25k-30k', `emp_cnt`='', `click_cnt`=NULL, `degree_cond`='13', `school_cond`=NULL, `exp_cond`='5-10年', `start_date`=NULL, `end_date`=NULL, `recruit_type`=3, `special_cond`='10001,10013,10017,10016,10020,10019', `sys_recommend`=NULL, `child_job_flag`=1, `STATUS`=1, `create_id`=15790741, `create_time`='2023-04-25 14:43:15', `update_id`=NULL, `update_time`='2025-06-26 14:51:30', `district`=NULL, `trade_circle`=NULL, `subway_station`=NULL, `job_kind_id`='30,3029', `is_above`=2, `is_comp_addr`=NULL, `departments_name`='', `post_opt_com_1`=NULL, `post_opt_com_2`=NULL, `post_opt_com_3`=NULL, `audit_flag`=NULL, `pub_range`='0000000000', `introversion_status`=NULL, `bonus_status`=NULL, `min_exp`=5, `max_exp`=10, `old_job_id`=NULL, `keywords`='', `zbw_status`=NULL, `offer_resume_cnt`=0, `job51_channel_resume_cnt`=0, `zhilian_channel_resume_cnt`=0, `liepin_channel_resume_cnt`=0, `channel_resume_cnt`=0, `bonus_resume_cnt`=0, `introversion_resume_cnt`=0, `deliver_resume_cnt`=0, `resume_cnt`=NULL, `module`=13, `hunter_comp_type`=1, `hh_job_comp_id`=769562, `hh_job_comp_name`='中电建物业管理有限公司', `channel_comp_field`='', `channel_comp_field_id`='', `channel_comp_type`=NULL, `channel_comp_size`=NULL, `is_channel_job`=NULL, `inside_audits`=0, `is_anonymity`=0, `anonymity_info`=NULL, `zhilian_status`=NULL, `job51_status`=NULL,