UPDATE `matcheasy_new`.`c_job` SET `job_id`=1776, `company_id`=8038732, `project_id`=NULL, `job_name`='资产评估岗', `departments`=NULL, `citys`='北京', `job_duty`='首创集团总部——资产评估管理岗\n工作职责：\n1.履行低效资产清单企业退出的经济行为审批程序。\n2.履行资产评估核准备案项目审核程序，具体包括：对重要项目进行现场调研，参与评估项目访谈；组织外部评审专家开展审核资产评估报告，同步开展审核并汇总审核意见；完成核心事项审核工作底稿，编制评估项目备忘录；履行集团总办会备案程序。\n3.指导所属企业开展资产评估工作，并组织资产评估专项检查及日常业务培训。\n4.根据市国资委要求，完成产权登记及产权整改工作。\n基本素质要求：\n硕士，资产评估或财经类专业；\n勤于思考，善于发现并解决问题，富有钻研精神，学习能力强；\n责任心强，工作态度积极主动，耐心细致；\n具备较强的沟通协调能力，与国资委、二级企业和相关部门沟通顺畅；\n具有较强的文字功底，善于工作的归纳提升、总结报告。\n专业素质要求：\n取得资产评估师执业资格；\n具备5年以上大型评估事务所执业经验；\n擅长环保、金融行业评估业务，熟悉国有资产评估管理制度及要求；\n具有扎实的理论基础、深厚的专业知识，以及丰富的评估报告审核工作经验，能够独立完成评估报告审核工作，并结合国有资产评估管理的要求准确判断项目风险。', `experi_qlft`=NULL, `proc_id`=NULL, `min_salary`=0.00, `max_salary`=0.00, `salary`='面议', `emp_cnt`='1', `click_cnt`=NULL, `degree_cond`='11', `school_cond`=NULL, `exp_cond`='不限', `start_date`=NULL, `end_date`=NULL, `recruit_type`=3, `special_cond`='10007,10002,10003', `sys_recommend`=NULL, `child_job_flag`=1, `STATUS`=1, `create_id`=94746638, `create_time`='2024-05-07 10:44:35', `update_id`=NULL, `update_time`='2025-06-26 14:51:30', `district`=NULL, `trade_circle`=NULL, `subway_station`=NULL, `job_kind_id`='35,3501', `is_above`=2, `is_comp_addr`=NULL, `departments_name`='资产管理部', `post_opt_com_1`=NULL, `post_opt_com_2`=NULL, `post_opt_com_3`=NULL, `audit_flag`=NULL, `pub_range`='0000000000', `introversion_status`=NULL, `bonus_status`=NULL, `min_exp`=0, `max_exp`=100, `old_job_id`=NULL, `keywords`='', `zbw_status`=1, `offer_resume_cnt`=0, `job51_channel_resume_cnt`=0, `zhilian_channel_resume_cnt`=0, `liepin_channel_resume_cnt`=0, `channel_resume_cnt`=0, `bonus_resume_cnt`=0, `introversion_resume_cnt`=0, `deliver_resume_cnt`=0, `resume_cnt`=NULL, `module`=13, `hunter_comp_type`=1, `hh_job_comp_id`=355585, `hh_job_comp_name`='', `channel_comp_field`='', `channel_comp_field_id`='', `channel_comp_type`=NULL, `channel_comp_size`=NULL, `is_channel_job`=0, `inside_audits`=0, `is_anonymity`=NULL, `anonymity_info`='某