UPDATE `matcheasy_new`.`c_job` SET `job_id`=1383, `company_id`=1019519, `project_id`=NULL, `job_name`='投资经理', `departments`=NULL, `citys`='北京', `job_duty`='1、定期收集、跟踪、通报公司发展方向城市的士地信息;\n2、收集项目拓展信息，进行项目初选，提出立项建议，编制立项报告;\n3、负责公司负责区域内的产业地产、收并购等类型项目的前期市场调研、分析定位及可行性分析，汇编可行性研究报告及项目策划方案，并提交上级评审决策;\n4、负责拟投资项目的测算;\n5、参与产业地产、收并购等类型项目的投资谈判，编制项目交易结构、控制项目风险;\n6、跟进项目可研区域公司审批、集团投委会、经办会、董事会审批流程，并跟进参与竟买前的审批流程;\n7、负责公司内部上报项目的所有流程和跟进;\n8、负责新项目土地治谈，撰写土地合同，跟进项目竟买审批程序、竟买手续准备，负责项目获取后的各项手续办理及用地移交;\n9、负责项目全过程后的项目后评估及归档工作，负责项目未获取的后续收尾工作;\n10、投后项目跟踪;\n11、上级交办的其他事项。\n任职资格\n1、全日制本科及以上学历，房地产管理、金融学、经济学、市场营销、土地资源管理、规划设计类等相关专业;\n2、三年以上产业地产相关工作经验者优先;\n3、精通并参与过产业地产和收并购项目，了解产业地产、收并购项目土地政策、开发政策开发流程，了解国家、地区房地产行业关于土地流转、房地产开发、建筑规划等法律法规及相关政策;\n4、熟悉商务谈判，具有敏锐的市场洞察力和有效沟通能力，具备良好的研究分析能力、拓展公关能力、资源整合能力;\n5、抗压性强，适应出差。\n', `experi_qlft`=NULL, `proc_id`=NULL, `min_salary`=20.00, `max_salary`=25.00, `salary`='20k-25k', `emp_cnt`='1', `click_cnt`=NULL, `degree_cond`='13', `school_cond`=NULL, `exp_cond`='3-10年', `start_date`=NULL, `end_date`=NULL, `recruit_type`=3, `special_cond`='10001,10009,10013,10016,10015', `sys_recommend`=NULL, `child_job_flag`=1, `STATUS`=2, `create_id`=15790741, `create_time`='2023-03-23 16:46:22', `update_id`=NULL, `update_time`='2024-03-26 14:32:48', `district`=NULL, `trade_circle`=NULL, `subway_station`=NULL, `job_kind_id`='30,3040', `is_above`=2, `is_comp_addr`=NULL, `departments_name`='', `post_opt_com_1`=NULL, `post_opt_com_2`=NULL, `post_opt_com_3`=NULL, `audit_flag`=NULL, `pub_range`='0000000000', `introversion_status`=NULL, `bonus_status`=NULL, `min_exp`=3, `max_exp`=10, `old_job_id`=NULL, `keywords`='', `zbw_status`=NULL, `offer_resume_cnt`=0, `job51_channel_resume_cnt`=0, `zhilian_channel_resume_cnt`=0, `liepin_channel_resume_cnt`=0, `channel_resume_cnt`=0, `bonus_resume_cnt`=0, `introversion_resume_cnt`=0, `deliver_resume_cnt`=0, `resume_cnt`=NULL, `module`=13, `hunter_comp_type`=1, `hh_job_comp_id`=896932, `hh_job_comp_name`='五矿建设投资管理（北京）有限公司', `channel_comp_field`='', `channel_comp_