UPDATE `matcheasy_new`.`c_job` SET `job_id`=1379, `company_id`=1019519, `project_id`=NULL, `job_name`='体检中心主任', `departments`=NULL, `citys`='北京', `job_duty`='一、岗位职责\n（一）负责健管中心日常管理工作，主要包括健管中心\n规划、医疗、护理、设备、信息智能化、工程等相关工作，\n及时向公司汇报健管中心各项工作、结合工作中的问题提出\n建议、落实执行；\n（二）根据公司战略规划要求，负责体检中心的经营管\n理工作，定期向公司汇报医院的经营状况；跟踪业界动态和\n医改政策变化，为经营决策提供参考；\n（三）熟悉体检中心的运营管理，全面统筹管理各部门，\n有效开展团队建设，培养，激励工作，管控运营成本，提高\n经济效益；\n（四）建立健全管理体系，根据公司规章制度监督各部\n门工作，保障医疗质量和医疗安全，提升服务质量，严防客\n人投诉，保证体检中心工作正常有序开展；\n（五）良好的公共关系，对外处理医疗单位、上级管理\n部门之间的事宜，维护关系。\n（六）完成通用技术宝石花医疗总部分管领导和主要领\n导交办的其他工作。\n二、任职要求：\n（一）具有大学本科以上文化程度，临床医学相关专业；\n（二）具有 5 年以上健康管理中心管理工作经验，中共\n党员身份优先考虑；\n（三）具有现代化医疗机构管理经营意识，对健康管理\n项目各个模块熟悉，有成功运营经验；\n（四）优秀的团队领导能力及强烈的全局意识，较强的\n团队建设能力，沟通协调能力，有强烈的工作责任感和事业\n心，具有开疆拓土的精神', `experi_qlft`=NULL, `proc_id`=NULL, `min_salary`=30.00, `max_salary`=35.00, `salary`='30k-35k', `emp_cnt`='1', `click_cnt`=NULL, `degree_cond`='13', `school_cond`=NULL, `exp_cond`='5-10年', `start_date`=NULL, `end_date`=NULL, `recruit_type`=3, `special_cond`='10002,10006,10017,10020', `sys_recommend`=NULL, `child_job_flag`=1, `STATUS`=1, `create_id`=15790741, `create_time`='2023-03-20 10:21:16', `update_id`=NULL, `update_time`='2024-03-26 14:32:48', `district`=NULL, `trade_circle`=NULL, `subway_station`=NULL, `job_kind_id`='31,3124', `is_above`=2, `is_comp_addr`=NULL, `departments_name`='健康管理中心', `post_opt_com_1`=NULL, `post_opt_com_2`=NULL, `post_opt_com_3`=NULL, `audit_flag`=NULL, `pub_range`='0000000000', `introversion_status`=NULL, `bonus_status`=NULL, `min_exp`=5, `max_exp`=10, `old_job_id`=NULL, `keywords`='', `zbw_status`=NULL, `offer_resume_cnt`=0, `job51_channel_resume_cnt`=0, `zhilian_channel_resume_cnt`=0, `liepin_channel_resume_cnt`=0, `channel_resume_cnt`=0, `bonus_resume_cnt`=0, `introversion_resume_cnt`=0, `deliver_resume_cnt`=0, `resume_cnt`=NULL, `module`=13, `hunter_comp_type`=1, `hh_job_comp_id`=790471, `hh_job_comp_name`='宝石花医疗集团', `channel_comp_field`='', `channel_comp_field_id`='', `channel_comp_type`=NULL, `channel_comp_size